'use strict';
// Capitol Quest: Complete Record — gameplay and presentation layer.
// All character, portrait, landmark, tile and effect art comes from the supplied atlas.
const BASIC_NAMES={TRUMP:'Power Punch',HEGSETH:'Rifle Shot',LUTNICK:'Cash Toss',RFK:'Signal Bolt'};
const ROLES={TRUMP:'VANGUARD',HEGSETH:'MARKSMAN',LUTNICK:'BROKER',RFK:'MEDIC'};
const ACCENTS={TRUMP:'#f8ce76',HEGSETH:'#99d4af',LUTNICK:'#8fc9ff',RFK:'#b7a0f4'};
const extraAtlas=new Image();extraAtlas.src='assets/extras.png';
let buttons=[],pointer={x:-1,y:-1},modal=null,supplyIndex=0,allyIndex=0;
const TILE={grass:[1447,331,27,23],paving:[1279,51,39,34],water:[1279,127,43,37],floor:[1422,394,36,17],carpet:[1194,404,31,39],shelf:[1473,429,52,56],column:[1263,405,37,53],door:[1421,421,44,53],desk:[1464,501,59,37]};
const REST={MALL:{x:1720,y:705},GROUNDS:{x:470,y:1165},ROTUNDA:{x:470,y:915},ARCHIVE:{x:450,y:1115},PRESS:{x:470,y:1040},HEARING:{x:1050,y:930}};
const BREAKERS=[{x:400,y:720,label:'01 · WEST'},{x:1220,y:710,label:'02 · EAST'},{x:1740,y:450,label:'03 · NORTH'}];
const CATALOG=[{x:445,y:350,label:'Intake · 04'},{x:1065,y:400,label:'Transfer · 17'},{x:1380,y:680,label:'Release · 29'}];
const ROOM_NAMES={MALL:'01 / THE RALLY',GROUNDS:'02 / SERVICE ROUTE',ROTUNDA:'03 / THE CHECKPOINT',ARCHIVE:'04 / PAPER TRAIL',PRESS:'05 / DEAD AIR',HEARING:'06 / ON THE RECORD'};
function adv(){return state.adventure;}
function panelText(s,x,y,size=16,color='#dce5f3',align='left'){text(s,x,y,size,color,align,500);}
function box(x,y,w,h,fill='#101d30',stroke='#34465b'){ctx.fillStyle=fill;ctx.fillRect(x,y,w,h);ctx.strokeStyle=stroke;ctx.lineWidth=1;ctx.strokeRect(x+.5,y+.5,w-1,h-1);}
function pill(s,x,y,color='#f8ce76'){const w=String(s).length*8+20;box(x,y,w,23,'#12263a',color);panelText(s,x+10,y+4,12,color);}
function uiButton(label,x,y,w,h,fn,{active=false,disabled=false,sub='',accent='#f8ce76'}={}){
  const hot=pointer.x>=x&&pointer.x<x+w&&pointer.y>=y&&pointer.y<y+h;
  box(x,y,w,h,active?'#29364a':hot&&!disabled?'#223148':'#142238',active?accent:'#3b4b60');
  if(active){ctx.fillStyle=accent;ctx.fillRect(x,y,4,h);}
  panelText(label,x+15,y+(sub?11:(h-17)/2),16,disabled?'#758295':active?accent:'#eef3fb');
  if(sub)panelText(sub,x+15,y+36,12,disabled?'#758295':'#a6b7ce');
  buttons.push({x,y,w,h,fn,disabled,label});
}
function wrapped(s,x,y,w,size=16,color='#b8c7da',lines=3){return wrap(s,x,y,w,size*1.5,size,color,lines);}
function rule(x,y,w){ctx.fillStyle='#304056';ctx.fillRect(x,y,w,1);}
function drawExtra(key,x,y,w,h,frame=0){const q=EXTRA[key];const r=Array.isArray(q?.[0])?q[frame]:q;if(!r||!extraAtlas.complete||!extraAtlas.naturalWidth)return;ctx.drawImage(extraAtlas,...r,Math.round(x),Math.round(y),Math.round(w),Math.round(h));}
drawItem=function(key,x,y,size=38){const r=EXTRA[key];if(!r)return;const sc=size/Math.max(r[2],r[3]);drawExtra(key,x-r[2]*sc/2,y-r[3]*sc/2,r[2]*sc,r[3]*sc);};
// Distances along the actual path, independent of frames per second.
resetTrail=function(){trail=[{x:state.player.x,y:state.player.y,dir:state.player.dir,frame:0}];lastTrailPoint={...trail[0]};trailDistance=0;};
function recordTrail(){const p=state.player;trail.unshift({x:p.x,y:p.y,dir:p.dir,frame:p.frame});let d=0,end=trail.length;for(let i=1;i<trail.length;i++){d+=dist(trail[i-1],trail[i]);if(d>240){end=i+1;break;}}trail.length=end;lastTrailPoint={...trail[0]};}
function followerAt(distance){let pts=[{...state.player},...trail],remaining=distance;for(let i=1;i<pts.length;i++){const d=dist(pts[i-1],pts[i]);if(d>=remaining&&d>0){const t=remaining/d;return {x:lerp(pts[i-1].x,pts[i].x,t),y:lerp(pts[i-1].y,pts[i].y,t),dir:pts[i-1].dir,frame:state.player.frame};}remaining-=d;}return {...pts[pts.length-1],frame:0};}
function recoverPlayerPosition(){const p=state.player,m=currentMap();p.x=clamp(Number(p.x)||m.spawn.x,110,m.w-110);p.y=clamp(Number(p.y)||m.spawn.y,120,m.h-120);if(!collides(p.x,p.y))return;for(let r=24;r<Math.max(m.w,m.h);r+=24)for(let a=0;a<Math.PI*2;a+=Math.PI/16){const x=p.x+Math.cos(a)*r,y=p.y+Math.sin(a)*r;if(x>110&&y>120&&x<m.w-110&&y<m.h-100&&!collides(x,y)){p.x=x;p.y=y;return;}}}
walkMeta=function(name,dir,frame){let seq;if(dir==='up')seq=name==='TRUMP'||name==='HEGSETH'?[4,5,4,5]:[3,4,5,4];else if(dir==='down')seq=[0,1,2,1];else seq=name==='TRUMP'?[2,3,2,3]:[2,2,2,2];return ACT.walk[name][seq[frame%4]];};
drawPartySprite=function(name,dir,frame,x,y,scale=1,alpha=1){const base={TRUMP:77,HEGSETH:84,LUTNICK:81,RFK:97}[name],sc=72/base*scale;const meta=walkMeta(name,dir,frame);drawActorFrame(meta,x,y,sc,dir==='left',alpha);};
drawWorldEntities=function(){const actors=npcList().map(n=>({y:n.y,draw:()=>drawNPC(n)}));for(const mob of WORLD_ENCOUNTERS[state.zone]||[]){if(state.defeated[mobKey(state.zone,mob.id)])continue;const mm=worldMobMotion[mobKey(state.zone,mob.id)]||mob;actors.push({y:mm.y,draw:()=>drawMob(mob,mm)});}['HEGSETH','LUTNICK','RFK'].forEach((name,i)=>{const tp=followerAt(46*(i+1));if(dist(tp,state.player)<12)return;actors.push({y:tp.y,draw:()=>{drawShadow(tp.x,tp.y,21,.2);drawPartySprite(name,tp.dir,tp.frame,tp.x,tp.y,1,.98);}});});actors.push({y:state.player.y,draw:()=>{drawShadow(state.player.x,state.player.y,23);drawPartySprite('TRUMP',state.player.dir,state.player.frame,state.player.x,state.player.y,1);}});actors.sort((a,b)=>a.y-b.y).forEach(a=>a.draw());};
drawNPC=function(n){drawShadow(n.x,n.y,22,.2);if(ACT.npc[n.sprite])drawNpcSprite(n.sprite,n.x,n.y,1.05);else drawEnemySprite(n.sprite,n.x,n.y,.66);if(dist(n,state.player)<200){const w=n.name.length*8+20;box(n.x-w/2,n.y-101,w,25,'#0b172bdd','#52718b');panelText(n.name,n.x,n.y-96,13,'#eff5ff','center');}};
drawMob=function(m,mm){drawShadow(mm.x,mm.y,22,.22);drawEnemySprite(m.type,mm.x,mm.y,.66,mm.dir==='right');drawDiamond(mm.x,mm.y-91,encounterGrace>0?'#8994a2':'#fb9285',6);};
const baseUpdateWorld=updateWorld;
updateWorld=function(dt){state.player.speed=keys.has('shift')?310:205;baseUpdateWorld(dt);};
const baseMerge=mergeState;
mergeState=function(dst,src){baseMerge(dst,src);const defaults=freshState().adventure;dst.adventure={...defaults,...src.adventure,upgrades:{...defaults.upgrades,...src.adventure?.upgrades},chests:{...src.adventure?.chests},visited:{MALL:true,...src.adventure?.visited}};dst.party=freshState().party.map((p,i)=>{const saved=src.party?.find(q=>q.name===p.name)||src.party?.[i]||{};return {...p,...saved,status:{},alive:(saved.hp??p.hp)>0};});};
const baseTransition=zoneTransition;
zoneTransition=function(zone,spawn){adv().visited[zone]=true;baseTransition(zone,spawn);};
// The buildings use their original atlas tiles. The floor patterns are cached, never stretched scenery.
function tileRect(key,x,y,w,h,size=64){const r=TILE[key];if(!atlasReady||!r)return;ctx.save();ctx.beginPath();ctx.rect(x,y,w,h);ctx.clip();for(let yy=y;yy<y+h;yy+=size)for(let xx=x;xx<x+w;xx+=size)drawImageRect(r,xx,yy,size,size);ctx.restore();}
drawOutdoorBase=function(m){tileRect('grass',0,0,m.w,m.h,64);tileRect('paving',0,655,m.w,170,64);tileRect('paving',m.w*.46,90,160,m.h-180,64);tileRect('paving',190,895,m.w-370,340,64);if(state.zone==='MALL'){box(638,443,784,169,'#b7beb8','#dae0d2');tileRect('water',650,455,760,145,64);for(let i=0;i<8;i++){ctx.fillStyle='#d8f2ff44';ctx.fillRect(675+i*89,479+(i%3)*37,37,2);}}drawTreeLines(m);};
drawInteriorBase=function(m,theme){tileRect('floor',0,0,m.w,m.h,64);ctx.fillStyle=theme==='archive'?'#49332533':theme==='press'?'#17366355':'#171b2d22';ctx.fillRect(0,0,m.w,m.h);tileRect('carpet',0,80,m.w,72,64);};
drawColumn=function(x,y){drawImageRect(TILE.column,x,y,75,150);};
drawShelf=function(x,y,h){tileRect('shelf',x,y,210,h,105);};
drawDesk=function(x,y,w,h){tileRect('desk',x,y,w,h,100);};
drawReadingTable=function(x,y){drawDesk(x,y,510,115);};
drawHedges=function(x,y,w,h){tileRect('grass',x,y,w,h,48);for(let xx=x;xx<x+w-45;xx+=78)drawLandmark('TREE',xx,y-25,1.6);};
const baseDrawObjects=drawMapObjects;
drawMapObjects=function(z){baseDrawObjects(z);const rest=REST[z];drawItem('MEDKIT',rest.x,rest.y-16,32);pill('REST',rest.x-26,rest.y+7,'#95deb8');if(z==='GROUNDS')BREAKERS.forEach((b,i)=>{pill(b.label,b.x-48,b.y-125,adv().breakers.includes(i)?'#95deb8':'#f8ce76');});if(z==='ARCHIVE')CATALOG.forEach((c,i)=>{if(!adv().catalog.includes(i)){drawItem('FILE',c.x,c.y-25,36);}});};
const baseInteractables=interactables;
interactables=function(){const arr=baseInteractables(),a=adv(),z=state.zone;const rest=REST[z];arr.push({id:'rest',...rest,label:'Rest & save',run:()=>{state.party.forEach(p=>{p.hp=p.maxHp;p.mp=p.maxMp;p.alive=true;p.status={};});saveGame(false);notify('HP & MP RESTORED · PROGRESS SAVED');sfx('heal');}});
 if(z==='MALL'){arr.push({id:'upgrade',x:600,y:1190,label:'Party training',icon:'FILE',run:()=>{modal={type:'upgrade',selection:0};}});arr.push({id:'tutorial',x:750,y:1160,label:'Practice encounter',run:()=>startBattle([{type:'PROTESTER',level:2}],{gold:0,practice:true,label:'PRACTICE · Learn to break an enemy'})});}
 if(z==='GROUNDS'){BREAKERS.forEach((b,i)=>arr.push({id:'breaker'+i,...b,label:'Relay switch '+(i+1),run:()=>{if(a.breakers.includes(i)){notify('SWITCH ALREADY POWERED');return;}a.breakers.push(i);notify(`RELAY POWER ${a.breakers.length}/3`);sfx('save');saveGame(false);}}));const cart=arr.find(i=>i.id==='megaphone'),run=cart.run;cart.run=()=>{if(a.breakers.length<3){notify('RESTORE THE THREE RELAY SWITCHES · '+a.breakers.length+'/3');return;}run();saveGame(false);};}
 if(z==='ARCHIVE'){CATALOG.forEach((c,i)=>arr.push({id:'catalog'+i,...c,hidden:()=>a.catalog.includes(i),label:c.label,run:()=>{a.catalog.push(i);notify('CATALOG CARD FOUND · '+c.label.toUpperCase());saveGame(false);}}));const ledger=arr.find(i=>i.id==='ledger'),run=ledger.run;ledger.run=()=>{if(!a.archiveOpen){modal={type:'archive',selection:0};return;}run();saveGame(false);};}
 if(z==='PRESS'){arr.push({id:'channel',x:1215,y:710,label:'Tune relay channel',icon:'USB',run:()=>{modal={type:'channel',selection:0};}});const fixer=arr.find(i=>i.id==='fixer'),run=fixer.run;fixer.run=()=>{if(!a.channelOpen){notify('THE CONTROL ROOM IS JAMMED · TUNE THE RELAY FIRST');return;}run();};}
 if(z==='HEARING'){[{x:415,y:480,label:'Submit source originals'},{x:1030,y:480,label:'Submit verification card'}].forEach((p,i)=>arr.push({id:'brief'+i,...p,hidden:()=>a.briefs.includes(i),icon:'DOC',run:()=>{if(!state.flags.factChecked){notify('GET FACT CHECKER SIGN-OFF FIRST');return;}a.briefs.push(i);notify('HEARING EVIDENCE FILED · '+a.briefs.length+'/2');saveGame(false);}}));const chair=arr.find(i=>i.id==='chair'),run=chair.run;chair.run=()=>{if(a.briefs.length<2){notify('FILE BOTH EVIDENCE PACKAGES AT THE SIDE DESKS');return;}run();};}
 const caches={MALL:{x:190,y:570},GROUNDS:{x:1790,y:280},ROTUNDA:{x:1140,y:410},ARCHIVE:{x:1100,y:860},PRESS:{x:1330,y:520},HEARING:{x:200,y:880}};
 if(caches[z])arr.push({id:'cache',...caches[z],icon:'FILE',label:'Supply cache',hidden:()=>a.chests[z],run:()=>{a.chests[z]=true;state.cash+=65;state.inventory.SERUM++;state.inventory.MEDKIT++;notify('CACHE · +65 CASH · SERUM · MEDKIT');saveGame(false);}});
 return arr;};
const baseObjective=getObjective;
getObjective=function(){const a=adv(),z=state.zone;if(state.mainStage===2&&a.breakers.length<3){const i=BREAKERS.findIndex((_,i)=>!a.breakers.includes(i));return {...BREAKERS[i],zone:'GROUNDS',label:`Restore relay switches (${a.breakers.length}/3)`};}if(state.mainStage===4&&!a.archiveOpen){if(a.catalog.length<3){const i=CATALOG.findIndex((_,i)=>!a.catalog.includes(i));return {...CATALOG[i],zone:'ARCHIVE',label:`Collect catalog cards (${a.catalog.length}/3)`};}return {zone:'ARCHIVE',x:950,y:860,label:'Open the ledger vault · Intake → Transfer → Release'};}if(state.mainStage===5&&!state.flags.fixer&&!a.channelOpen)return {zone:'PRESS',x:1215,y:710,label:'Tune the relay · channel 2 / 4 / 1'};if(state.mainStage===7&&a.briefs.length<2)return {zone:'HEARING',x:a.briefs.includes(0)?1030:415,y:480,label:`File the hearing evidence (${a.briefs.length}/2)`};return baseObjective();};
function battleTargets(){if(battle.pending?.targetType==='enemy')return aliveEnemies();if(battle.pending?.kind==='item'&&ITEMS[battle.pending.item]?.revive)return state.party;return aliveParty();}
function weakness(e){return ['Armored','Guard','Tech'].some(t=>e.trait.includes(t))?'magic':e.trait.includes('Media')||e.trait.includes('Quick')?'hybrid':'physical';}
function attackType(a){if(a.kind==='basic')return a.actor.name==='RFK'?'magic':a.actor.name==='LUTNICK'?'hybrid':'physical';return a.skill?.kind.replace('All','')||'none';}
const baseResolvePlayer=resolvePlayerAction;
resolvePlayerAction=function(a){const enemies=(a.target?[a.target]:a.targets||[]).filter(t=>battle.enemies.includes(t));const snapshots=enemies.map(t=>t.hp);baseResolvePlayer(a);enemies.forEach((e,i)=>{if(e.hp>=snapshots[i]||e.hp<=0)return;if(attackType(a)===weakness(e)&&!e.resolveTurns){e.breakPoints=(e.breakPoints||0)+1;addFloater(e,'WEAK','#f8ce76');if(e.breakPoints>=2){e.breakPoints=0;e.broken=true;addStatus(e,'vulnerable',2);battle.message+=' BREAK! Enemy loses its next action.';addFloater(e,'BREAK!','#84e4fa');}}});};
function planIntent(e){if(e.broken)return {kind:'broken',label:'BROKEN · skips turn',power:0};const n=battle.round;if(e.boss&&n%3===0)return {kind:'sweep',label:'CHARGING · party hit',power:.95};if(e.hp/e.maxHp<.4&&['nurse','senior'].includes(e.ai))return {kind:'heal',label:'Recover HP',power:1};if(n%3===2&&['veteran','union','sentinel'].includes(e.ai))return {kind:'guard',label:'Brace · armor up',power:1};return {kind:['teacher','journalist','scientist','fixer','chair','activist'].includes(e.ai)?'magic':'physical',label:['teacher','journalist','scientist','fixer','chair','activist'].includes(e.ai)?'Signal strike':'Physical strike',power:e.boss?1.25:1};}
function refreshIntents(){battle.enemies.forEach(e=>{e.intent=planIntent(e);});}
const baseStartBattle=startBattle;
startBattle=function(specs,reward={}){baseStartBattle(specs,reward);if(!battle)return;refreshIntents();battle.message=reward.practice?'PRACTICE · Hit a weakness twice to BREAK an enemy. Defend against charged attacks.':`${reward.label||'ENCOUNTER'} · Read enemy intentions before choosing.`;battle.autoTimer=0;};
const baseStartEnemy=startEnemyAction;
startEnemyAction=function(){const round=battle.round;baseStartEnemy();if(battle&&battle.round!==round)refreshIntents();};
resolveEnemyAction=function(e){if(e.broken){e.broken=false;e.intent=planIntent(e);battle.message=`${e.name} is broken and loses its turn.`;return;}const move=e.intent||planIntent(e),living=aliveParty();if(!living.length)return loseBattle();battle.message=`${e.name}: ${move.label}.`;if(move.kind==='guard'){e.guard=true;addStatus(e,'defUp',2);addFx('buff',enemyPos(e).x,enemyPos(e).y-60);return;}if(move.kind==='heal'){const n=Math.min(e.maxHp-e.hp,Math.round(e.maxHp*.2));e.hp+=n;addFloater(e,'+'+n,'#95deb8');return;}const targets=move.kind==='sweep'?living:[choice(living)];for(const t of targets){const magic=move.kind==='magic'||(move.kind==='sweep'&&['fixer','chair'].includes(e.ai));applyDamage(t,magic?damageMagic(e,t,move.power):damagePhysical(e,t,move.power));addFx(magic?'magic':'hit',partyPos(t).x,partyPos(t).y-65);}if(!aliveParty().length)loseBattle();};
// Results use game time and explicit confirmation, never stale wall-clock callbacks.
winBattle=function(){if(!battle||battle.phase==='victory')return;const r=battle.reward;const xp=r.practice?0:r.boss?320:115,gold=r.practice?0:r.gold??50;state.cash+=gold;if(!r.practice){adv().battles++;state.party.forEach(p=>{p.xp+=xp;p.limit=Math.min(100,p.limit+22);levelCheck(p);});}if(r.worldMob)state.defeated[r.worldMob]=true;if(r.boss==='SENTINEL'){state.flags.sentinel=true;setStage(4);}if(r.boss==='FIXER')state.flags.fixer=true;if(r.boss==='CHAIR'){state.flags.chair=true;setStage(8);}battle.phase='victory';battle.result={xp,gold};battle.message=r.practice?'PRACTICE COMPLETE · No supplies or health lost.':`VICTORY · +${gold} cash · +${xp} XP to each party member`;sfx('victory');};
loseBattle=function(){if(!battle)return;battle.phase='defeat';battle.message='FALL BACK · Retry this encounter or recover at the nearest rest point.';};
function retreat(){state.party.forEach(p=>{p.hp=p.maxHp;p.mp=p.maxMp;p.alive=true;p.status={};});battle=null;mode='world';const r=REST[state.zone];state.player.x=r.x;state.player.y=r.y+45;recoverPlayerPosition();resetTrail();encounterGrace=3;saveGame(false);}
function retryBattle(){const specs=battle.enemies.map(e=>({type:e.type,level:e.level})),reward=battle.reward;state.party.forEach(p=>{p.hp=p.maxHp;p.mp=p.maxMp;p.alive=true;p.status={};});battle=null;mode='world';startBattle(specs,reward);}
const oldFinish=finishBattle;
finishBattle=function(won,escaped){if(battle?.reward.practice){state.party.forEach((p,i)=>{const old=battle.practiceParty?.[i];if(old)Object.assign(p,old);});if(battle.practiceInventory)state.inventory={...battle.practiceInventory};}oldFinish(won,escaped);};
const startBattleWithIntents=startBattle;
startBattle=function(specs,reward={}){const party=JSON.parse(JSON.stringify(state.party)),inventory={...state.inventory};startBattleWithIntents(specs,reward);if(reward.practice){battle.practiceParty=party;battle.practiceInventory=inventory;}};
const oldBattleInput=battleInput;
battleInput=function(k){if(k==='e')k='enter';if(battle.phase==='victory'&&(k==='enter'||k===' ')){finishBattle(true,false);return;}if(battle.phase==='defeat'){if(k==='enter'||k===' ')retryBattle();if(k==='escape')retreat();return;}if(battle.phase==='input'&&(k==='6'||((k==='enter'||k===' ')&&battle.menuIndex===5))){if(battle.reward.boss){battle.message='This checkpoint must be cleared. Defend, heal, or break the boss.';sfx('error');return;}finishBattle(false,true);return;}oldBattleInput(k);};
const baseUpdateBattle=updateBattle;
updateBattle=function(dt){baseUpdateBattle(dt);if(battle?.phase==='message'&&battle.pending?.advanceAfterMessage){battle.autoTimer=(battle.autoTimer||0)+dt;if(battle.autoTimer>.55){battle.autoTimer=0;advancePlayer();}}else if(battle)battle.autoTimer=0;};
partyPos=function(p){return [{x:174,y:292},{x:122,y:420},{x:336,y:360},{x:505,y:430}][state.party.indexOf(p)]||{x:174,y:292};};
enemyPos=function(e){const n=battle.enemies.length,i=battle.enemies.indexOf(e);return (n===1?[{x:985,y:374}]:n===2?[{x:875,y:330},{x:1110,y:397}]:[{x:815,y:335},{x:1000,y:401},{x:1150,y:285}])[i]||{x:985,y:374};};
function useFieldItem(key,target){const item=ITEMS[key];if(!state.inventory[key])return notify('NO '+item.name.toUpperCase()+' LEFT');if(!target.alive&&!item.revive)return notify('USE A MEDKIT TO REVIVE THIS ALLY');if(item.heal&&target.hp===target.maxHp||item.mp&&target.mp===target.maxMp)return notify('ALREADY FULL');state.inventory[key]--;if(item.heal){target.hp=Math.min(target.maxHp,target.hp+item.heal);target.alive=target.hp>0;}if(item.mp)target.mp=Math.min(target.maxMp,target.mp+item.mp);sfx('heal');saveGame(false);}
function buyUpgrade(i){const p=state.party[i],tier=adv().upgrades[p.name]||0,cost=140+tier*120;if(tier>=2)return notify('TRAINING COMPLETE');if(state.cash<cost)return notify('NEED '+cost+' CASH');state.cash-=cost;adv().upgrades[p.name]=tier+1;p.maxHp+=30;p.hp=Math.min(p.maxHp,p.hp+30);p.maxMp+=12;p.mp=Math.min(p.maxMp,p.mp+12);p.atk+=i===0||i===1?7:3;p.mag+=i===2||i===3?7:3;notify(p.label+' TRAINING UPGRADED');saveGame(false);}
function modalInput(k){if(k==='escape'){modal=null;return;}const a=adv();if(modal.type==='upgrade'){if(['arrowup','w'].includes(k))modal.selection=(modal.selection+3)%4;if(['arrowdown','s'].includes(k))modal.selection=(modal.selection+1)%4;if(['enter','e',' '].includes(k))buyUpgrade(modal.selection);return;}if(modal.type==='archive'){if(['arrowleft','a','arrowup','w'].includes(k))modal.selection=(modal.selection+2)%3;if(['arrowright','d','arrowdown','s'].includes(k))modal.selection=(modal.selection+1)%3;if(['1','2','3'].includes(k)){modal.selection=+k-1;k='enter';}if(['enter','e',' '].includes(k)){if(a.catalog.length<3){notify('FIND ALL THREE CATALOG CARDS FIRST');return;}a.archiveCode.push(modal.selection);if(a.archiveCode.length===3){if(a.archiveCode.join()==='0,1,2'){a.archiveOpen=true;modal=null;notify('VAULT UNLOCKED · RECOVER THE RED LEDGER');saveGame(false);}else{a.archiveCode=[];notify('WRONG ORDER · INTAKE → TRANSFER → RELEASE');sfx('error');}}}return;}if(modal.type==='channel'){if(['arrowleft','a'].includes(k))modal.selection=(modal.selection+2)%3;if(['arrowright','d'].includes(k))modal.selection=(modal.selection+1)%3;if(['arrowup','w'].includes(k))a.channel[modal.selection]=(a.channel[modal.selection]+1)%5;if(['arrowdown','s'].includes(k))a.channel[modal.selection]=(a.channel[modal.selection]+4)%5;if(['enter','e',' '].includes(k)){if(a.channel.join()==='2,4,1'){a.channelOpen=true;modal=null;notify('RELAY RESTORED · CONTROL ROOM ACCESS OPEN');saveGame(false);}else{notify('SIGNAL MISMATCH · MATCH 2 / 4 / 1');sfx('error');}}}};
const originalHandle=handleInput;
handleInput=function(k){if(modal)return modalInput(k);if(overlay==='status'){if(['escape','i'].includes(k)){overlay=null;return;}if(['arrowup','w'].includes(k))supplyIndex=(supplyIndex+5)%6;if(['arrowdown','s'].includes(k))supplyIndex=(supplyIndex+1)%6;if(['arrowleft','a'].includes(k))allyIndex=(allyIndex+3)%4;if(['arrowright','d'].includes(k))allyIndex=(allyIndex+1)%4;if(['enter','e',' '].includes(k))useFieldItem(Object.keys(ITEMS)[supplyIndex],state.party[allyIndex]);return;}originalHandle(k);};
const originalUpdate=update;
update=function(dt){if(modal){totalTime+=dt;if(toast.time>0)toast.time-=dt;return;}originalUpdate(dt);};
