function drawNavigator(){const ob=getObjective();if(!ob)return;let target=ob;if(ob.zone!==state.zone){const route=['MALL','GROUNDS','ROTUNDA','ARCHIVE','PRESS','HEARING'],here=route.indexOf(state.zone),dest=route.indexOf(ob.zone),next=route[here+(dest>here?1:-1)];const names={MALL:'toMall',GROUNDS:'toGrounds',ROTUNDA:'toRotunda',ARCHIVE:'toArchive',PRESS:'toPress',HEARING:'toHearing'};const exit=interactables().find(i=>i.id===names[next]);if(exit)target=exit;else return;}const sx=target.x-camera.x,sy=target.y-camera.y;if(sx>50&&sx<W-50&&sy>92&&sy<WORLD_VIEW_H-55){ctx.strokeStyle='#f8ce76';ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(sx,sy+8,27,10,0,0,Math.PI*2);ctx.stroke();return;}const dx=sx-W/2,dy=sy-WORLD_VIEW_H/2,k=Math.min((W/2-40)/Math.max(1,Math.abs(dx)),(WORLD_VIEW_H/2-70)/Math.max(1,Math.abs(dy))),x=W/2+dx*k,y=WORLD_VIEW_H/2+dy*k;ctx.save();ctx.translate(x,y);ctx.rotate(Math.atan2(dy,dx));ctx.fillStyle='#f8ce76';ctx.beginPath();ctx.moveTo(13,0);ctx.lineTo(-9,-9);ctx.lineTo(-9,9);ctx.closePath();ctx.fill();ctx.restore();}
drawWorldHUD=function(){box(18,18,550,73,'#0b172bea','#4c6680');panelText(ROOM_NAMES[state.zone],34,31,12,'#8ab4cd');text(MAPS[state.zone].name,34,53,20,'#fff2d2');box(806,18,456,73,'#0b172bea','#4c6680');panelText('NEXT OBJECTIVE',824,29,11,'#8ab4cd');wrapped(getObjective()?.label||'Case complete · free exploration',824,49,418,14,'#f7dd9b',2);drawNavigator();box(0,WORLD_VIEW_H,W,H-WORLD_VIEW_H,'#0c172a','#52708a');state.party.forEach((p,i)=>{const x=18+i*249;box(x,565,237,100,'#142238',allyIndex===i&&overlay==='status'?ACCENTS[p.name]:'#34465b');drawPortrait(p.name,x+10,575,54,67);panelText(p.label,x+75,576,14,ACCENTS[p.name]);panelText('HP '+p.hp+' / '+p.maxHp,x+75,598,12,'#eaf1fc');bar(x+75,618,145,7,p.hp,p.maxHp,'#99d4af');panelText('MP '+p.mp+' / '+p.maxMp,x+75,636,12,'#a7cbef');});uiButton('I · Supplies',1030,566,232,44,()=>{overlay='status';});uiButton('Esc · Pause',1030,621,232,44,()=>{mode='pause';pauseSelection=0;});const ni=nearestInteraction();panelText(ni?'E · '+(ni.data.label||ni.data.name):'Shift · Sprint     M · Map     Q · Journal',24,685,14,ni?'#f8ce76':'#92a8c0');panelText('$'+state.cash+'  ·  USB '+state.evidence.usb+'/4',1000,685,14,'#f8ce76','right');if(ni)buttons.push({x:0,y:670,w:630,h:50,fn:()=>interact(),label:'Interact'});};
drawBattleBackground=function(){ctx.fillStyle='#34577c';ctx.fillRect(0,0,W,300);const sky=ctx.createLinearGradient(0,70,0,305);sky.addColorStop(0,'#365780');sky.addColorStop(1,'#9fbdca');ctx.fillStyle=sky;ctx.fillRect(0,0,W,305);for(let x=0;x<W;x+=78)drawLandmark('TREE',x,182,2);drawLandmark('CAPITOL',576,82,2);tileRect('paving',0,301,W,169,64);if(!['MALL','GROUNDS'].includes(state.zone)){tileRect('floor',0,70,W,400,64);tileRect('carpet',530,80,220,390,64);for(let x of [40,265,970,1195])drawImageRect(TILE.column,x,94,72,143);drawImageRect(A.interior.SEAL,594,100,90,88);ctx.fillStyle=state.zone==='PRESS'?'#13285355':'#36232322';ctx.fillRect(0,70,W,400);}const vignette=ctx.createLinearGradient(0,300,0,470);vignette.addColorStop(0,'#050c1500');vignette.addColorStop(1,'#050c1555');ctx.fillStyle=vignette;ctx.fillRect(0,300,W,170);};
drawBattleUnits=function(){state.party.forEach(p=>{const pos=partyPos(p),sc=BATTLE_SCALE[p.name];let x=pos.x,y=pos.y,meta=ACT.action[p.name][0];drawShadow(x,y,30,.25);if(battle.phase==='action'&&battle.action?.actor===p){const a=battle.action,t=clamp(a.t/a.duration,0,1),off=attackType(a)!=='none';const strike=t<.38?t/.38:t>.7?(1-t)/.3:1;if(off&&p.name==='TRUMP'&&(a.kind==='basic'||a.skill?.kind==='physical')){const target=a.target||a.targets?.[0],dest=target?enemyPos(target).x-100:x+72;const dash=t<.42?Math.sin(t/.42*Math.PI/2):t>.57?Math.cos(clamp((t-.57)/.4,0,1)*Math.PI/2):1;x=lerp(pos.x,dest,dash);}else if(off&&p.name==='TRUMP')x+=Math.sin(t*Math.PI)*40;else if(off)x+=Math.sin(t*Math.PI)*12;if(t>.17&&t<.85)meta=ACT.action[p.name][a.pose??0];}if(p.hitTimer)x+=Math.sin(totalTime*80)*5;drawActorFrame(meta,x,y,sc,false,p.alive?1:.28);if(p.guard)pill('GUARD',pos.x-32,pos.y-160,'#a3d6ff');if(battle.phase==='input'&&currentActor()===p){drawDiamond(pos.x,pos.y-157,ACCENTS[p.name],8);ctx.strokeStyle=ACCENTS[p.name];ctx.lineWidth=2;ctx.beginPath();ctx.ellipse(pos.x,pos.y+3,38,10,0,0,Math.PI*2);ctx.stroke();}if(battle.phase==='target'&&battle.pending?.targetType==='ally'){const selected=battleTargets()[battle.targetIndex]===p;if(selected){ctx.strokeStyle='#95deb8';ctx.lineWidth=3;ctx.strokeRect(pos.x-48,pos.y-142,96,149);}if(battleTargets().includes(p))buttons.push({x:pos.x-65,y:pos.y-145,w:130,h:154,label:p.label,fn:()=>{battle.targetIndex=battleTargets().indexOf(p);confirmBattleTarget(p);}});}});
 battle.enemies.forEach(e=>{const pos=enemyPos(e),sc=e.boss?1.18:1.04;let x=pos.x;if(battle.phase==='enemyAction'&&battle.action?.actor===e&&!e.broken)x-=Math.sin(clamp(battle.action.t/battle.action.duration,0,1)*Math.PI)*48;if(e.hitTimer)x+=Math.sin(totalTime*80)*5;drawShadow(pos.x,pos.y,33,.26);drawEnemySprite(e.sprite,x,pos.y,sc,false,e.hp>0?1:.18);if(e.hp>0){box(pos.x-82,pos.y+9,164,46,'#0b172bdd','#43566e');panelText(e.name,pos.x,pos.y+15,13,'#f0f3fa','center');bar(pos.x-69,pos.y+36,138,7,e.hp,e.maxHp,'#e89080');const intent=e.broken?'BREAK · loses turn':e.intent?.label||'';const iy=pos.y-ACT.enemy[e.sprite].r[3]*sc-31;box(pos.x-100,iy,200,23,'#0b172bdf',e.broken?'#7fdaeb':e.intent?.kind==='sweep'?'#f8ce76':'#617a8e');panelText(intent,pos.x,iy+5,11,e.broken?'#7fdaeb':'#f3dfb4','center');if(battle.phase==='target'&&battle.pending?.targetType==='enemy'||battle.phase==='analyze'){const selected=aliveEnemies()[battle.targetIndex]===e;if(selected){ctx.strokeStyle='#f8ce76';ctx.lineWidth=3;ctx.strokeRect(pos.x-83,pos.y-143,166,198);}buttons.push({x:pos.x-85,y:pos.y-145,w:170,h:200,label:e.name,fn:()=>{battle.targetIndex=aliveEnemies().indexOf(e);battleInput('enter');}});}}});};
drawBattleEffects=function(){for(const fx of spriteFx){const frames=EXTRA[fx.kind];if(!frames)continue;const i=Math.min(frames.length-1,Math.floor(fx.t/fx.duration*frames.length)),r=frames[i],sc=1.6;ctx.globalAlpha=1-fx.t/fx.duration*.45;drawExtra(fx.kind,fx.x-r[2]*sc/2,fx.y-r[3]*sc/2,r[2]*sc,r[3]*sc,i);}ctx.globalAlpha=1;for(const f of floaters){ctx.globalAlpha=clamp(f.life/.9,0,1);ctx.strokeStyle='#0b1526';ctx.lineWidth=4;ctx.font='700 19px "QuestMono", monospace';ctx.textAlign='center';ctx.strokeText(f.text,f.x,f.y);text(f.text,f.x,f.y,19,f.color,'center');}ctx.globalAlpha=1;};
