// Small original chiptune score. Synthesized locally; no external audio or network dependency.
let musicBeat=0,musicClock=0,musicScene='';
function musicNote(midi,duration,gain=.012,type='triangle'){if(!audioCtx||audioCtx.state!=='running')return;const o=audioCtx.createOscillator(),g=audioCtx.createGain(),t=audioCtx.currentTime;o.type=type;o.frequency.value=440*Math.pow(2,(midi-69)/12);g.gain.setValueAtTime(0,t);g.gain.linearRampToValueAtTime(gain,t+.015);g.gain.exponentialRampToValueAtTime(.0001,t+duration);o.connect(g);g.connect(audioCtx.destination);o.start(t);o.stop(t+duration+.02);}
function updateMusic(dt){if(!state.settings.sound||!audioCtx||mode==='pause')return;const scene=mode==='battle'?'battle':'world';if(scene!==musicScene){musicScene=scene;musicBeat=0;musicClock=0;}musicClock-=dt;if(musicClock>0)return;const tempo=scene==='battle'?.19:.34;musicClock=tempo;const roots=scene==='battle'?[45,45,41,43]:[48,43,45,41],root=roots[Math.floor(musicBeat/16)%4],melody=scene==='battle'?[0,7,12,10,7,3,7,12]:[0,7,12,7,3,10,7,3];musicNote(root+12+melody[musicBeat%8],tempo*.85,scene==='battle'?.011:.008,'triangle');if(musicBeat%4===0)musicNote(root,tempo*3.8,.014,'triangle');if(scene==='battle'&&musicBeat%2===0)musicNote(30,tempo*.23,.008,'square');musicBeat++;}
