const tilePatterns=new Map();
tileRect=function(key,x,y,w,h,size=64){const r=TILE[key];if(!atlasReady||!r)return;const cacheKey=key+':'+r.join(',')+':'+size;let pattern=tilePatterns.get(cacheKey);if(!pattern){const tile=document.createElement('canvas');tile.width=size;tile.height=size;const tc=tile.getContext('2d');tc.imageSmoothingEnabled=false;tc.drawImage(atlas,...r,0,0,size,size);pattern=ctx.createPattern(tile,'repeat');tilePatterns.set(cacheKey,pattern);}ctx.save();ctx.translate(x,y);ctx.fillStyle=pattern;ctx.fillRect(0,0,w,h);ctx.restore();};
